#include "poi/PoiCatalogue.hpp"
#include <algorithm>
namespace elysium::poi{namespace{void norm(std::vector<std::uint64_t>&v){v.erase(std::remove(v.begin(),v.end(),0),v.end());std::sort(v.begin(),v.end());v.erase(std::unique(v.begin(),v.end()),v.end());}bool allCaps(const std::vector<std::uint64_t>&have,const std::vector<std::uint64_t>&need){return std::includes(have.begin(),have.end(),need.begin(),need.end());}}
PoiValidationError PoiCatalogue::publish(PoiDef d){if(!d.contentId)return PoiValidationError::InvalidContentId;if(defs_.contains(d.contentId))return PoiValidationError::DuplicateId;if(!d.factionMask)return PoiValidationError::InvalidFaction;if(!d.silhouetteFamilyContentId)return PoiValidationError::MissingSilhouette;if(!d.approachDecisionContentId)return PoiValidationError::MissingDecisionValue;if(!d.laterOwnerContentId)return PoiValidationError::MissingOwner;norm(d.serviceCapabilityContentIds);const bool hasHook=d.traversalHookContentId||d.rewardDomainContentId||!d.serviceCapabilityContentIds.empty()||d.standingAdapterContentId||d.knowledgeAdapterContentId||d.industryAdapterContentId;if(!hasHook)return PoiValidationError::Behaviorless;if(d.persistenceClass==PoiPersistenceClass::RegenerableBaseline&&!d.rewardDomainContentId&&!d.traversalHookContentId&&!d.knowledgeAdapterContentId&&!d.industryAdapterContentId&&!d.standingAdapterContentId&&d.serviceCapabilityContentIds.empty())return PoiValidationError::MissingPersistenceIntent;defs_[d.contentId]=std::move(d);return PoiValidationError::None;}
const PoiDef*PoiCatalogue::find(std::uint64_t id)const{auto i=defs_.find(id);return i==defs_.end()?nullptr:&i->second;}std::vector<PoiDef>PoiCatalogue::ordered()const{std::vector<PoiDef>o;for(auto&[_,d]:defs_)o.push_back(d);return o;}std::vector<std::uint64_t>PoiCatalogue::eligible(const PoiEligibility&q)const{auto need=q.requiredCapabilities;norm(need);std::vector<std::uint64_t>o;for(auto&[id,d]:defs_)if(d.domain==q.domain&&(d.factionMask&q.acceptedFactionMask)&&allCaps(d.serviceCapabilityContentIds,need))o.push_back(id);return o;}
} // namespace elysium::poi
